data_and_hook_calls:
usePublicClient | useState | useEffect | publicClient.getBlockNumber | getLogsChunked(
            publicClient,
            {
              address: loopAddress,
              event: legacyClaimEventAbiItem,
              fromBlock,
              toBlock,
            },
            chunkSize
          ).then | getLogsChunked | getLogsChunked(
            publicClient,
            {
              address: loopAddress,
              event: upgradedClaimEventAbiItem,
              fromBlock,
              toBlock,
            },
            chunkSize
          ).then | fetchLogs

usePublicClient | useState | useEffect | publicClient.getBlockNumber | getLogsChunked(
            publicClient,
            {
              address: loopAddress,
              event: legacyRegisterEventAbiItem,
              args: {
                periodNumber,
              },
              fromBlock,
              toBlock,
            },
            chunkSize
          ).then | getLogsChunked | getLogsChunked(
            publicClient,
            {
              address: loopAddress,
              event: upgradedRegisterEventAbiItem,
              args: {
                periodNumber,
              },
              fromBlock,
              toBlock,
            },
            chunkSize
          ).then | fetchLogs
